    ctx.beginPath(); ctx.ellipse(cx, cy - 8 * kick, w * .75 * pop * (1 + .25 * kick), h * .8 * pop * (1 + .25 * kick), 0, 0, Math.PI * 2); ctx.fill(); ctx.restore();
