const DUMMY = (pack('tutorial').dummy || {});                               // Marcin's dummy: idle + hit (Dummy.psd)
const DUMMY_X = 3000, DUMMY_SCALE = .62, DUMMY_FOOT = [757, 1880];   // where it stands (world x of its pole), its size, its foot in the PSD
