// ---------- the beat lessons: which beats get a dot (and a woodblock), and how a press went
function tutMarked(b) {
  if (tut.on && tut.step === 'feel') return true;      // every beat
  return (tut.on || RUSH_DOTS) && rushDot(b);          // the rush's green window (normal play too)
}
