  if (posX + CX > DUMMY_X - DUMMY_WALL) { posX = DUMMY_X - DUMMY_WALL - CX; walkBump(now); }
  if (tut.step !== 'walk' && tut.step !== 'talk' && posX + CX < DUMMY_X - DUMMY_FAR) posX = DUMMY_X - DUMMY_FAR - CX;
  if (tut.key > .3) lights[[3, 2, 1, 0, 4][((Math.floor(hb * 4) % 5) + 5) % 5]] = 1;   // the keytar's lights run along it on 16ths
