// ---------- gamepad: PS4/PS5 and Xbox pads (Gamepad API, "standard" mapping). Polled once per frame from frame() ----------
// LT = acid to the left, RT = acid to the right (hold), left stick = walk, X / A = Shroom Rush (like Space),
// Circle / B = jump (like W).
// Any button advances a dialogue or restarts after death. It calls the same functions as the mouse and keyboard.
const PAD_DEAD = .35;                                  // stick dead zone (worn sticks drift to ~.2)
const PAD_TRIG = .3;                                   // how far a trigger goes down before it counts as held
const pad = { prev: [], walk: 0, face: 0, held: [] };  // walk: -1/0/1, face: side a held trigger plays to (1 = left, like facing)
function padReleaseAll() { if (pad.held.length) acidPress(false); pad.held = []; pad.face = 0; pad.walk = 0; }
function pollPad() {
  const gp = [...(navigator.getGamepads ? navigator.getGamepads() : [])].find(p => p && p.connected);
  if (!gp) { if (pad.prev.length) { padReleaseAll(); pad.prev = []; } return; }
  const now = gp.buttons.map((b, i) => i === 6 || i === 7 ? b.value > PAD_TRIG : b.pressed);
  const prev = pad.prev, down = i => now[i] && !prev[i], up = i => !now[i] && prev[i];
  const anyDown = now.some((on, i) => on && !prev[i]);
  pad.prev = now;
  if (down(9) && !onTitle && !calib.active) { togglePause(); padReleaseAll(); return; }   // Options / Start = pause
  if (PAUSE.on) { pad.walk = 0; return; }
  const x = gp.axes[0] || 0;
  pad.walk = Math.abs(x) > PAD_DEAD ? Math.sign(x) : 0;
  if (calib.active) { pad.walk = 0; if (anyDown) calibTap(gp.timestamp); return; }   // (the van: it comes before the title)
  if (onTitle) { if (anyDown) leaveTitle(); return; }
  if (gameMs() - leftTitleAt < 300) return;   // the press that closed the title screen
  if (allDown()) { pad.walk = 0; if (anyDown && document.getElementById('death').classList.contains('ready')) restart(); return; }
  if (talk.active) { pad.walk = 0; if (anyDown) advanceTalk(); return; }
  if (anyDown) { initAudio(); hideHint(); }
  if (down(0) && (!COOP || CAR) && !tutSpace()) { if (building(beatNow())) dropMash(); else castHats(); }   // (co-op: the rush is the goblin's; in the van one player does it all)
  if (down(1) && (!building(beatNow()) || COOP) && !tutLock() && !dead && jumpH === 0 && jumpV === 0) jumpV = JUMP_V * Math.sqrt(rushJump());   // like W
  for (const [i, side] of [[6, 1], [7, -1]]) {
    if (down(i) && (!building(beatNow()) || COOP)) {             // (building the drop: only the mash counts, like the mouse)
      if (!pad.held.length) acidPress(true);
      pad.held = pad.held.filter(s => s !== side).concat(side);
    }
    if (up(i) && pad.held.includes(side)) {
      pad.held = pad.held.filter(s => s !== side);
      if (!pad.held.length) acidPress(false);
    }
  }
  if (!acid.held) pad.held = [];                       // a dialogue or death let go of the acid
  pad.face = pad.held.length ? pad.held[pad.held.length - 1] : 0;   // both held: the last one pressed wins
  if (pad.face) aim.on = false;                        // the pad took over aiming; the mouse gets it back when it moves
}


// ---------- latency calibration: the SOUNDCHECK page. A first visit opens on it (boot.js), before anything else loads: a black
// screen, the bard's head asks you to tap to the kick. Only his head and the kick are loaded, so nothing slows the taps.
// TVs, Bluetooth and consoles add delay the browser doesn't report. latencyFix (s) is subtracted in heardTime(), so
// beatNow() (every hit window, every visual) moves with it. 4 taps in a row on the kick = done. Saved per browser, then the
// page you were headed for loads (the van, on a first visit). ?calib forces it; the "latency" button comes back here ----------
// The head nods when YOU tap, never on its own beat: a visual beat would be tapped to instead of the kick and teach us nothing.
