  if (hot && hot !== sel) { const b = boxOf(hot); if (b) { ctx.setLineDash([5, 4]); ctx.strokeStyle = 'rgba(224,162,66,.8)'; ctx.lineWidth = 1.5; ctx.strokeRect(b[0] - 4, b[1] - 4, b[2] - b[0] + 8, b[3] - b[1] + 8); lab(b, elName(hot), 'rgba(224,162,66,.8)'); } }
  if (sel) {
    const b = boxOf(sel);
    if (b) {
      ctx.setLineDash([7, 4]); ctx.strokeStyle = '#e0a242'; ctx.lineWidth = 2; ctx.strokeRect(b[0] - 4, b[1] - 4, b[2] - b[0] + 8, b[3] - b[1] + 8);
      const n = cyc && cyc.stack.includes(sel) ? ` · layer ${cyc.stack.indexOf(sel) + 1}/${cyc.stack.length}` : '';
      lab(b, elName(sel) + n, '#e0a242');
      if (movable(sel)) { ctx.setLineDash([]); ctx.fillStyle = '#e0a242'; ctx.strokeStyle = '#2a1a1e'; ctx.lineWidth = 2; ctx.fillRect(b[2] - 6, b[3] - 6, 12, 12); ctx.strokeRect(b[2] - 6, b[3] - 6, 12, 12); }
    }
  }
