  num('e-dx', v => { o().dx = v; }); num('e-dy', v => { o().dy = v; });
  num('e-sn', v => { o().s = Math.max(.2, v / 100); $('e-s').value = v; });
  if ($('e-s')) $('e-s').oninput = e => { snap(); o().s = e.target.value / 100; $('e-sn').value = e.target.value; saveStyle(); applyDom(); };
