    const b = selScreenBox();
    document.body.style.cursor = SE.arm ? 'copy' : b && Math.abs(x - b[2]) < 12 && Math.abs(y - b[1]) < 12 ? 'nesw-resize' : SE.hover ? 'move' : edgeAt(x) !== null ? 'ew-resize' : 'grab';
    return;
