  const arrow = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, 1], ArrowDown: [0, -1] }[e.code];
  if (arrow && !p) { e.preventDefault(); SE.cam.x += arrow[0] * (e.shiftKey ? 2000 : 400) / SE.cam.z; return; }
  if (!p) return;
