    h += `<div class="wv${on ? ' on' : ''}" data-w="${i}"><div class="sum"><b>${i + 1}</b> · ${sum} · ${W.width || AREA_W}${n ? ` · ${n} prop${n > 1 ? 's' : ''}` : ''}${W.tough !== undefined ? ' · tough ' + W.tough : ''}</div>`;
