  const g = ac.createGain(), src = ac.createBufferSource(); src.buffer = buf; src.connect(g); g.connect(carBus); src.start(t);
  carSrc = { src, g, buf, i, at: t, prev: auto ? carSrc : null }; carSong = buf;
