function carAcid() {                                   // the acid button in the van: go where the map points, or next song at the amp
  const now = gameMs() / 1000;
  if (carLocked()) return;
  if (mapReady(now)) { mapGo(); return; }
  if (!ac || !nearAmp() || mapBusy(now)) return;
  playSong((carPlay.want + 1) % CAR_SONG.length);
}
const nearAmp = () => Math.abs(carX - AMP.x) < AMP.near;

// ---------- the frame
const around = (M, p, tx, ty, rot, sx = 1, sy = 1) => M.translate(p[0] + tx, p[1] + ty).rotate(rot).scale(sx, sy).translate(-p[0], -p[1]);
