  const want = talk.active || carLocked() || mapBusy(now) ? 0 : ((keys.r ? 1 : 0) - (keys.l ? 1 : 0) || pad.walk || tch.walk);
  const nx = Math.max(CAR_WALK[0], Math.min(CAR_WALK[1], carX + want * SPEED * dt)), dir = nx !== carX ? want : 0;
  carX = nx; moving = !!dir; back = 0;
