  const arm = (rest, shoulder, a, i, [tx, ty, tr]) => W.body.translate(rest[0], rest[1] + 8 * kick + 4 * breathe + 3 * i * kick)
    .translate(...shoulder).rotate(a + 1.5 * breathe * (i ? -1 : 1)).translate(-shoulder[0], -shoulder[1])
    .translate(tx, ty).rotate(tr).translate(-tx, -ty);
  W.hand1 = arm(HANDS.rest1, HANDS.sh1, handS.a[0], 0, HANDS.turn1);
  W.hand2 = arm(HANDS.rest2, HANDS.sh2, handS.a[1], 1, HANDS.turn2);
