  const G = CIMG.glow;
  ctx.shadowColor = C('car-light', 'window', L.glow); ctx.shadowBlur = L.glowR * k * dpr;
  ctx.globalAlpha = L.glow * .3; ctx.drawImage(G.im, G.x, G.y, G.w, G.h);
  ctx.shadowBlur = 0; ctx.globalAlpha = 1;
