// ---------- sound: kick always, triplet psy bass opens up while walking. Both are Marcin's 8-beat sample loops
// (Sounds/PsyTranceLvL), locked to the beat grid; the Shroom Rush layers use the same loops (hats.js) ----------
const PSY = { ...pack('kick'), ...pack('psy') };
const PSY_LOOP = 8;                                    // beats per stem
const KICK_GAIN = .55, BASS_GAIN = .5;                 // the stems are hot (peaks ~1.4), the old synths sat about here
const psyBuf = {}, psyAt = { kick: 0, bass: 0, acid: 0 };       // decoded stems; the next loop (in beats) to schedule per stem
let ac, out, kickBus, bassBus, bassLP, noiseBuf, t0 = 0, muted = false;
let playLP;                                            // what HE plays (the acid, the rush, the drop) goes through this: a stage won sweeps it shut (waves.js)

// ---------- LEVELS. Level 1 = the psytrance stage: E Phrygian, day. Beat the Rave Goblin and level 2 starts on a 4-bar
// line a couple of bars later: Marcin's rock-funk stems (Sounds/RockFunkLvl_v2, the same slots as level 1) in B, at night.
// Both are 140 BPM. (The switch can still change the tempo: it re-anchors t0 on that line so the beat count runs on, and
// nothing is scheduled past it at the old tempo, since every loop plays in chunks that end on 8-beat lines and the switch
// happens one scheduler tick before the line.) ?level=2 starts there. Its stems are their own pack ('rock'): loaded with ?level=2,
// or when the switch is asked for ----------
const ROCK = () => pack('rock');                       // tools/prepare_rock_audio.py: Marcin's mix, untouched. A slot it lacks plays level 1's
// B C# D E F F# A: the B minor blues scale (1 b3 4 b5 5 b7) plus the 2nd (C#). The game's notes are written in E Phrygian:
// level 2 moves them up a fifth to B, then snaps them into this scale (C→C#, G→F#: the only two that don't fit)
const B_BLUES = [0, 2, 2, 3, 3, 5, 6, 7, 7, 10, 10, 12];   // semitones above B → the nearest note of the scale
const LEVELS = {
  1: { bpm: 140, root: 4, shift: 0, scale: null, night: 0, stems: () => PSY },
  2: { bpm: 140, root: 11, shift: 7, scale: B_BLUES, night: 1, stems: ROCK, title: 'Level 2', sub: 'rock funk · B minor blues' },
};
const LEVEL_LEAD = 8;                                  // beats: after the Rave Goblin's goodbye, night falls for at least this long before the switch
const LEVEL_START = +URL_FLAGS.get('level') === 2 ? 2 : 1;
let level = LEVEL_START;
const lvl = { want: level, minB: 0, at: null, shown: null };   // at: the beat the switch is set for; shown: its banner is still to come
const LV = () => LEVELS[level];
const lvNight = () => LEVELS[lvl.want].night;          // (the night of where we're headed: a boss win doesn't bring the day back in level 2)
BPM = LV().bpm;
night = nightTarget = LV().night;

const STEM = { 1: {}, 2: {} };                         // decoded stems per level; psyBuf holds the ones playing now
const decoding = { 1: false, 2: false };
function decodeStems() { for (const n of [1, 2]) decodeLevel(n); }   // (the ones whose pack is here)
function decodeLevel(n) {
  const st = LEVELS[n].stems();
  if (decoding[n] || !Object.keys(st).length) return;
  decoding[n] = true;
  for (const k in st)
    ac.decodeAudioData(b64buf(st[k])).then(b => { STEM[n][k] = b; if (level === n || (level === 2 && !(k in ROCK()))) psyBuf[k] = b; }).catch(e => console.warn('decode', n, k, e));
}
function setLevel(n, lead = 0) {                       // the switch waits for a free line at least `lead` beats away
  if (n === lvl.want) return;
  needPack(n === 2 ? 'rock' : 'psy').then(() => { if (ac) decodeLevel(n); });   // (its stems may join a little late: level 1's play meanwhile)
  lvl.want = n; lvl.at = null; lvl.minB = beatNow() + lead;
  nightTarget = lvNight();
}
function levelTick() {                                 // in the sequencer, before anything else gets scheduled
  if (lvl.want === level) return;
  const SPB = 60 / BPM, step = lvl.want === 1 ? PSY_LOOP : 16;   // (the rock loops are 16 beats: start them on their first)
  if (lvl.at === null) {
    if (drop.phase && lvl.want > level) return;       // the drop that beat him plays out first
    lvl.at = Math.ceil(Math.max(lvl.minB, (ac.currentTime + .25 - t0) / SPB) / step) * step;
  }
  const tB = t0 + lvl.at * SPB;
  if (tB > ac.currentTime + .18) return;               // next tick would schedule past it at the old tempo: now
  level = lvl.want; BPM = LV().bpm; t0 = tB - lvl.at * 60 / BPM;
  for (const k in psyBuf) delete psyBuf[k];
  Object.assign(psyBuf, level === 2 ? { ...STEM[1], ...STEM[2] } : STEM[1]);   // (level 2: its own stems over level 1's)
  acidDelay.delayTime.setValueAtTime(60 / BPM * .75, tB);
  if (LV().title) { crash(tB, true); lvl.shown = lvl.at; }
  lvl.at = null;
}
function updateLevel(now) {                            // the banner and a lightning strike, on the line you hear
  if (lvl.shown === null || beatNow() < lvl.shown) return;
  lvl.shown = null;
  banner(now, LV().title, LV().sub);
  lightning(now, posX + CX - facing * 900);   // (in front of him)
  for (let i = 0; i < 3; i++) rings.push({ x: posX + CX, y: FEET_Y - 500, t: now + i * .1, color: '#8a4fd0' });
}


